// src/facets/dash.rs: a demo that walks the path the record named (panic at tick 300, seed 7),
// so every later look replays it and a probe proves the end state.
use super::World;
use genex::prelude::*;

pub fn wire(game: &mut Game<World>) {
    game.demo("dash-into-wall", |d| {
        d.advance_ms(4_000); // up to the tick before the input that crashed it (about 240 ticks)
        d.inject(Input::key_tap(Key::Space)); // the input the record kept
        d.advance_ms(1_000); // past tick 300, where it panicked
        json!({ "dashes": d.sim().facets.get::<Dash>().dashes })
    });
}

